mapper.select:
SELECT r.code FROM t_base_user t, t_role_user e, t_role r WHERE t.id = e.user_id AND e.role_id = r.id
AND t.login_name = #{loginName}
AND t.phone = #{loginName}
AND t.is_valid = 1 and r.is_school = 1 AND t.status = 1

SELECT distinct r.CODE FROM t_base_user t, t_role_user e, t_role r WHERE t.id = e.user_id AND e.role_id = r.id AND t.is_valid = 1 and r.is_valid =1 and t.id = #{userId}
AND t.school_id = #{schoolId}
AND r.`code` = #{roleCode}

SELECT e.id, e.login_name, e.login_pwd, e.actual_name, e.nick_name, e.phone, e.id_card, e.birthday, e.email, e.department_id, e.is_leave, e.status, e.user_type, e.update_time, e.create_time FROM t_role_user er left join t_base_user e on er.user_id = e.id left join t_role r on er.role_id = r.id where er.is_valid =1 and e.is_valid =1 and r.is_valid =1 and e.approve_status=1 and e.status = 1
AND r.role_name like #{likeRoleName}
AND er.role_id = #{queryDTO.roleId}
AND (e.actual_name like #{likeQueryCriteria} OR e.phone like #{likeQueryCriteria} OR e.login_name like #{likeQueryCriteria})
and e.id is not null order by e.id desc
